export default class WeatherForecast extends WeatherResults {

    constructor(results, hourlyResults, showFahren){
        super(results, hourlyResults, showFahren);
        this.results = results;
        this.hourlyResults = hourlyResults;
        this.showFahren = showFahren;
    }


    convertDateTimeToWeekday = (datetime) => {
        let weekDay;
        const datetimesForDays = hourlyResults?.days;
        let divs = [];
        const date = new Date(datetime + 'T00:00:00');
        const weekDays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];   
        let dayIndex = date.getDay();
        return weekDay = weekDays[dayIndex];
    }

    if(datetimesForDays) {
        for(let i=0; i<14; i++){
        const datetime = datetimesForDays[i]?.datetime;
        const condition = datetimesForDays[i]?.conditions;
        const max = datetimesForDays[i]?.tempmax;
        const min = datetimesForDays[i]?.tempmin;
        weekDay = convertDateTimeToWeekday(datetime);
        divs.push(
            <div class="column daily-weather border-bottom-white gap-lg" key={i}>
                    <p>{weekDay}</p>
                    {/* <p>{temp}</p> */}
                    <p>{(max)}/{min}</p>
                    <p>{condition}</p>
                    <div class="flex">
                        <img src="../assets/uv.png" alt=""/>
                        <p>{datetimesForDays[i].uvindex}</p>
                    </div>

                    <p>{datetimesForDays[i].windspeed}</p>
                    <Test1></Test1>
            </div>
        );
    }
    }
    render(){
        return (
            <>
                <div class=" card row" className="card w-70">
                    {divs}
                </div>
            </>
        );
    }


}

